const $=(s,c=document)=>c.querySelector(s), $$=(s,c=document)=>[...c.querySelectorAll(s)];
document.addEventListener('DOMContentLoaded',()=>{mountChrome();mountLoader();document.body.classList.remove('loading');const h=$('.site-header'),t=$('.menu-toggle'),p=$('.scroll-progress');const onScroll=()=>{h?.classList.toggle('scrolled',scrollY>18);if(p){const max=document.documentElement.scrollHeight-innerHeight;p.style.width=`${max?scrollY/max*100:0}%`}};addEventListener('scroll',onScroll,{passive:true});onScroll();t?.addEventListener('click',()=>{const open=h.classList.toggle('open');t.setAttribute('aria-expanded',String(open))});$$('.nav a').forEach(a=>a.addEventListener('click',()=>h?.classList.remove('open')));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');io.unobserve(e.target)}}),{threshold:.12});$$('.reveal').forEach(el=>io.observe(el));loadSettings();initField()});
function mountLoader(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const first=!sessionStorage.getItem('rs-visited');const loader=document.createElement('div');loader.className=`page-loader${first?'':' is-short'}`;loader.setAttribute('aria-hidden','true');loader.innerHTML='<div class="loader-inner"><div class="loader-brand"><strong>RS</strong><span>REALIZE SUMMIT / LOADING</span></div><div class="loader-track"><div class="loader-bar"></div></div><div class="loader-count">ASCEND / 2026</div></div>';document.body.append(loader);sessionStorage.setItem('rs-visited','1');setTimeout(()=>loader.classList.add('is-done'),first?2200:620);document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||a.target==='_blank'||a.hasAttribute('download')||a.href.startsWith('mailto:')||a.origin!==location.origin||(a.pathname===location.pathname&&a.search===location.search))return;e.preventDefault();loader.classList.remove('is-done','is-short');loader.classList.add('is-exit');setTimeout(()=>location.href=a.href,560)})}
function mountChrome(){const page=document.body.dataset.page||'';const links=[['home','index.html','HOME'],['about','about.html','ABOUT'],['news','news.html','NEWS'],['members','members.html','MEMBERS'],['sponsors','sponsors.html','SPONSORS'],['contact','contact.html','CONTACT'],['shop','shop.html','SHOP']];const header=`<header class="site-header"><div class="scroll-progress"></div><div class="container header-inner"><a class="brand" href="index.html" aria-label="Realize Summit ホーム"><span class="brand-mark">RS</span><span>REALIZE SUMMIT</span></a><button class="menu-toggle" aria-label="メニューを開く" aria-expanded="false"><span></span><span></span></button><nav class="nav" aria-label="メインナビゲーション">${links.map(([id,href,label])=>`<a href="${href}" ${page===id?'aria-current="page"':''} class="${id==='shop'?'shop-link':''}">${label}</a>`).join('')}</nav></div></header>`;const footer=`<footer class="site-footer"><div class="container"><div class="footer-main"><a class="brand" href="index.html"><span class="brand-mark">RS</span><span>REALIZE SUMMIT</span></a><nav class="footer-links">${links.map(([,h,l])=>`<a href="${h}">${l}</a>`).join('')}</nav><div class="social-links"><a data-setting="x" href="#">X</a><a data-setting="youtube" href="#">YOUTUBE</a><a data-setting="twitch" href="#">TWITCH</a><a data-setting="discord" href="#">DISCORD</a></div></div><div class="copyright"><span>© 2026 REALIZE SUMMIT.</span><span>ALL RIGHTS RESERVED.</span></div></div></footer>`;$('#site-header')?.replaceWith(document.createRange().createContextualFragment(header));$('#site-footer')?.replaceWith(document.createRange().createContextualFragment(footer))}
async function loadSettings(){try{const s=await fetch('data/settings.json').then(r=>r.json());$$('[data-setting]').forEach(el=>{const k=el.dataset.setting;if(s[k]){if(el.tagName==='A')el.href=s[k];else el.textContent=s[k]}})}catch{}}
function initField(){const c=$('#hero-canvas');if(!c||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const x=c.getContext('2d'),mobile=innerWidth<700;let w,h,raf;const pts=Array.from({length:mobile?12:28},()=>({x:Math.random(),y:Math.random(),v:(Math.random()-.5)*.00012,s:Math.random()*1.3+.5}));function resize(){w=c.width=innerWidth*devicePixelRatio;h=c.height=c.clientHeight*devicePixelRatio}function draw(){x.clearRect(0,0,w,h);pts.forEach((p,i)=>{p.y=(p.y+p.v+1)%1;x.fillStyle=i%5===0?'rgba(125,17,27,.7)':'rgba(185,186,189,.22)';x.fillRect(p.x*w,p.y*h,p.s*devicePixelRatio,p.s*devicePixelRatio)});raf=requestAnimationFrame(draw)}addEventListener('resize',resize);document.addEventListener('visibilitychange',()=>{cancelAnimationFrame(raf);if(!document.hidden)draw()});resize();draw()}
